using System;
using System.Reflection;

class Program
{
    static int Add(int a, int b) { return a + b; }

    static void Main()
    {
        // The compiler stored IL bytes in the assembly; reflection can read them back.
        MethodInfo m = typeof(Program).GetMethod("Add", BindingFlags.NonPublic | BindingFlags.Static);
        byte[] il = m.GetMethodBody().GetILAsByteArray();
        Console.WriteLine("Add(2, 3) = " + Add(2, 3));
        Console.WriteLine("IL bytes: " + BitConverter.ToString(il));
        // 0x02 = ldarg.0, 0x03 = ldarg.1, 0x58 = add, 0x2A = ret
        Console.WriteLine("contains add opcode (0x58): " + (Array.IndexOf(il, (byte)0x58) >= 0));
        Console.WriteLine("ends with ret (0x2A): " + (il[il.Length - 1] == 0x2A));
    }
}

using System;

// A tiny model of tiered compilation: call counting promotes a method to Tier1.
class Method
{
    public string Name;
    public int Calls;
    public string Tier = "Tier0";
    public int Threshold = 30;      // the real runtime also waits for a start-up delay

    public void Call()
    {
        Calls++;
        if (Tier == "Tier0" && Calls >= Threshold)
        {
            Tier = "Tier1";          // background thread recompiled with full optimisation
            Console.WriteLine(Name + ": promoted to Tier1 after " + Calls + " calls");
        }
    }
}

class Program
{
    static void Main()
    {
        Method hot = new Method { Name = "HotMethod" };
        Method cold = new Method { Name = "ColdMethod" };
        for (int i = 0; i < 100; i++) hot.Call();
        for (int i = 0; i < 5; i++) cold.Call();
        Console.WriteLine(hot.Name + " calls=" + hot.Calls + " tier=" + hot.Tier);
        Console.WriteLine(cold.Name + " calls=" + cold.Calls + " tier=" + cold.Tier);
        // A method called once with a huge loop never reaches 30 calls: that is why OSR exists.
    }
}

using System;

// Model of the 64-bit .NET object size rule: 8 header + 8 MethodTable pointer + fields,
// rounded up to a multiple of 8, with a minimum of 24 bytes.
class Program
{
    static long ObjectSize(long fieldBytes)
    {
        long size = 16 + fieldBytes;
        size = (size + 7) / 8 * 8;       // round up to 8
        return Math.Max(24, size);       // minimum object size
    }

    static long ArraySize(long elemSize, long count)
    {
        // header + MT pointer + length (padded to 8) + elements, rounded to 8
        long size = 16 + 8 + elemSize * count;
        return (size + 7) / 8 * 8;
    }

    static long StringSize(int chars)
    {
        // header + MT + int length (padded) + UTF-16 chars + 2-byte null terminator
        long size = 16 + 4 + 2L * chars + 2;
        return (size + 7) / 8 * 8;
    }

    static void Main()
    {
        Console.WriteLine("new object()      = " + ObjectSize(0));
        Console.WriteLine("boxed int         = " + ObjectSize(4));
        Console.WriteLine("class {long,int}  = " + ObjectSize(12));
        Console.WriteLine("\"hello\"           = " + StringSize(5));
        Console.WriteLine("new int[3]        = " + ArraySize(4, 3));
    }
}

using System;
using System.Runtime.InteropServices;

[StructLayout(LayoutKind.Sequential)]
struct ByteIntByte { public byte A; public int B; public byte C; }

[StructLayout(LayoutKind.Sequential)]
struct IntByteByte { public int B; public byte A; public byte C; }

[StructLayout(LayoutKind.Sequential, Pack = 1)]
struct Packed { public byte A; public int B; public byte C; }

[StructLayout(LayoutKind.Explicit)]
struct Union { [FieldOffset(0)] public int AsInt; [FieldOffset(0)] public float AsFloat; }

class Program
{
    static void Main()
    {
        // Field order changes padding, so it changes the size
        Console.WriteLine("byte,int,byte      = " + Marshal.SizeOf(typeof(ByteIntByte)));
        Console.WriteLine("int,byte,byte      = " + Marshal.SizeOf(typeof(IntByteByte)));
        Console.WriteLine("Pack=1 byte,int,byte = " + Marshal.SizeOf(typeof(Packed)));
        Console.WriteLine("Explicit union     = " + Marshal.SizeOf(typeof(Union)));
        Union u = new Union();
        u.AsFloat = 1.0f;                          // both fields share the same 4 bytes
        Console.WriteLine("1.0f bits as int   = 0x" + u.AsInt.ToString("X"));
    }
}

using System;
using System.Runtime.CompilerServices;

class Buffer
{
    private readonly int[] data = { 10, 20, 30 };

    // Small hot method: easy for the JIT to inline, because the rare path is outside it
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public int Get(int i)
    {
        if ((uint)i >= (uint)data.Length) ThrowOutOfRange(i);
        return data[i];
    }

    // The ThrowHelper pattern: keeps the throw (big IL) out of the hot method
    [MethodImpl(MethodImplOptions.NoInlining)]
    private static void ThrowOutOfRange(int i)
    {
        throw new ArgumentOutOfRangeException("i", "index " + i + " is outside 0..2");
    }
}

class Program
{
    static void Main()
    {
        Buffer b = new Buffer();
        int sum = 0;
        for (int i = 0; i < 3; i++) sum += b.Get(i);
        Console.WriteLine("sum of Get(0..2) = " + sum);
        try { b.Get(7); }
        catch (ArgumentOutOfRangeException e) { Console.WriteLine("caught: " + e.Message.Split('\n')[0]); }
    }
}

using System;

class Program
{
    // Pattern 1: loop bound is a.Length, so the JIT can prove 0 <= i < a.Length
    static long SumFor(int[] a)
    {
        long s = 0;
        for (int i = 0; i < a.Length; i++) s += a[i];
        return s;
    }

    // Pattern 2: foreach over an array compiles to the same check-free loop
    static long SumForeach(int[] a)
    {
        long s = 0;
        foreach (int x in a) s += x;
        return s;
    }

    // Pattern 3: one explicit unsigned check dominates the access below it
    static int SafeGet(int[] a, int i)
    {
        if ((uint)i < (uint)a.Length) return a[i];   // the JIT skips a second check here
        return -1;
    }

    static void Main()
    {
        int[] a = { 4, 8, 15, 16, 23, 42 };
        Console.WriteLine("SumFor     = " + SumFor(a));
        Console.WriteLine("SumForeach = " + SumForeach(a));
        Console.WriteLine("SafeGet(2) = " + SafeGet(a, 2));
        Console.WriteLine("SafeGet(9) = " + SafeGet(a, 9));
        Console.WriteLine("SafeGet(-1)= " + SafeGet(a, -1));   // negative becomes huge as uint
    }
}

using System;
using System.Diagnostics;

class Program
{
    static int[] data;             // input prepared once, outside the timed code
    static long sink;              // consuming the result stops dead-code elimination

    static long Work()
    {
        long s = 0;
        for (int i = 0; i < data.Length; i++) s += data[i] * 2L;
        return s;
    }

    static void Main()
    {
        data = new int[100000];
        for (int i = 0; i < data.Length; i++) data[i] = i % 10;

        for (int i = 0; i < 20; i++) sink += Work();   // warm-up so the JIT has settled

        double[] ms = new double[7];
        for (int r = 0; r < ms.Length; r++)
        {
            Stopwatch sw = Stopwatch.StartNew();
            for (int i = 0; i < 50; i++) sink += Work();
            ms[r] = sw.Elapsed.TotalMilliseconds;
        }
        Array.Sort(ms);
        double median = ms[ms.Length / 2];             // median resists outliers better than mean
        Console.WriteLine("one Work() result = " + Work());
        Console.WriteLine("runs measured = " + ms.Length + ", median computed = " + (median >= 0));
        Console.WriteLine("result consumed = " + (sink > 0));
        // Timings differ per machine, so only the checks are printed.
    }
}

using System;
using System.Collections;
using System.Collections.Generic;

interface ICounter { void Inc(); }
struct Counter : ICounter
{
    public int N;
    public void Inc() { N++; }
}

class Program
{
    static void Main()
    {
        int x = 5;
        object a = x;                  // boxing: allocates a new heap object
        object b = x;                  // and another one
        Console.WriteLine("two boxes of 5 are the same object: " + ReferenceEquals(a, b));

        ArrayList old = new ArrayList();   // non-generic collection stores object -> boxes
        old.Add(1); old.Add(2);
        List<int> good = new List<int>(); // generic: no boxing
        good.Add(1); good.Add(2);
        Console.WriteLine("ArrayList item type: " + old[0].GetType().Name + ", List<int> sum: " + (good[0] + good[1]));

        Counter c = new Counter();
        ICounter boxed = c;            // copy of c is boxed
        boxed.Inc(); boxed.Inc();      // mutates the boxed copy only
        Console.WriteLine("original c.N = " + c.N + ", boxed copy N = " + ((Counter)boxed).N);

        int captured = 0;              // lambda capturing a local allocates a closure object
        Action add = () => captured++;
        add(); add();
        Console.WriteLine("captured = " + captured);
    }
}

using System;

class Program
{
    // Parses "12,7,305,41" and sums the numbers without Substring or Split:
    // we only track start/end indexes into the original string.
    static int SumCsv(string s)
    {
        int sum = 0, value = 0;
        for (int i = 0; i <= s.Length; i++)
        {
            if (i == s.Length || s[i] == ',')
            {
                sum += value;          // number finished: add it, nothing was allocated
                value = 0;
            }
            else value = value * 10 + (s[i] - '0');   // build the number digit by digit
        }
        return sum;
    }

    static void Main()
    {
        string line = "12,7,305,41";
        Console.WriteLine("input: " + line);
        Console.WriteLine("sum (no allocation in parser) = " + SumCsv(line));

        SumCsv(line);                                      // warm-up
        long before = GC.GetTotalMemory(false);
        int total = 0;
        for (int i = 0; i < 1000; i++) total += SumCsv(line);
        long after = GC.GetTotalMemory(false);
        Console.WriteLine("total over 1000 runs = " + total);
        Console.WriteLine("heap grew while parsing: " + (after - before > 100000));
        // Time O(n) per line, extra space O(1).
    }
}

using System;

class Program
{
    static void Main()
    {
        string a = "ab";
        string b = "a" + "b";                 // compile-time constant: interned like a literal
        string part = "a";
        string c = part + "b";                // built at run time: a new object
        Console.WriteLine("literal vs constant concat, same object: " + ReferenceEquals(a, b));
        Console.WriteLine("literal vs runtime concat, same object:  " + ReferenceEquals(a, c));
        Console.WriteLine("but == compares values:                    " + (a == c));

        string d = string.Intern(c);          // returns the pooled instance
        Console.WriteLine("after Intern, same object as literal:      " + ReferenceEquals(a, d));
        Console.WriteLine("IsInterned(\"ab\") returns the pooled one:  " + ReferenceEquals(string.IsInterned(c), a));
        Console.WriteLine("IsInterned of unseen text:                 " + (string.IsInterned(new string('z', 7)) == null));
    }
}

using System;

class Program
{
    static void Main()
    {
        int n = 2000000;
        int g0 = GC.CollectionCount(0);
        long keep = 0;
        for (int i = 0; i < n; i++)
        {
            byte[] tmp = new byte[100];     // a fresh short-lived array per iteration
            tmp[0] = 1;
            keep += tmp[0];
        }
        int allocGcs = GC.CollectionCount(0) - g0;

        g0 = GC.CollectionCount(0);
        byte[] reused = new byte[100];      // one buffer reused: no allocation in the loop
        for (int i = 0; i < n; i++)
        {
            reused[0] = 1;
            keep += reused[0];
        }
        int reuseGcs = GC.CollectionCount(0) - g0;

        Console.WriteLine("iterations: " + n + ", checksum: " + keep);
        Console.WriteLine("allocating loop triggered gen0 GCs: " + (allocGcs > 0));
        Console.WriteLine("reusing loop triggered fewer GCs:    " + (reuseGcs < allocGcs));
    }
}

using System;
using System.Threading;

class Program
{
    static long[] counters = new long[32];

    static void Run(int slot)
    {
        for (int i = 0; i < 2000000; i++) counters[slot]++;   // each thread writes its own slot
    }

    static void Main()
    {
        // Slots 0 and 1 are 8 bytes apart: same 64-byte cache line -> false sharing.
        // Slots 0 and 16 are 128 bytes apart: different cache lines.
        int[][] pairs = { new int[] { 0, 1 }, new int[] { 0, 16 } };
        string[] names = { "adjacent slots 0,1", "padded slots 0,16" };
        for (int p = 0; p < 2; p++)
        {
            Array.Clear(counters, 0, counters.Length);
            Thread t1 = new Thread(() => Run(pairs[p == 0 ? 0 : 1][0]));
            Thread t2 = new Thread(() => Run(pairs[p == 0 ? 0 : 1][1]));
            t1.Start(); t2.Start(); t1.Join(); t2.Join();
            long total = counters[pairs[p][0]] + counters[pairs[p][1]];
            Console.WriteLine(names[p] + ": total = " + total);
        }
        // Both give 4000000; the padded version is usually faster on multi-core CPUs
        // because the cores stop fighting over one cache line (timings vary per machine).
    }
}

using System;
using System.Collections.Generic;

static class Stats { public static int ObjectEquals; public static int TypedEquals; }

struct PlainKey                       // no IEquatable<T>: default comparer boxes
{
    public int X, Y;
    public override bool Equals(object o) { Stats.ObjectEquals++; PlainKey k = (PlainKey)o; return X == k.X && Y == k.Y; }
    public override int GetHashCode() { return X * 31 + Y; }
}

struct FastKey : IEquatable<FastKey>  // typed Equals: no boxing
{
    public int X, Y;
    public bool Equals(FastKey k) { Stats.TypedEquals++; return X == k.X && Y == k.Y; }
    public override bool Equals(object o) { return o is FastKey && Equals((FastKey)o); }
    public override int GetHashCode() { return X * 31 + Y; }
}

class Program
{
    static void Main()
    {
        Dictionary<PlainKey, int> d1 = new Dictionary<PlainKey, int>();
        Dictionary<FastKey, int> d2 = new Dictionary<FastKey, int>();
        d1[new PlainKey { X = 1, Y = 2 }] = 10;
        d2[new FastKey { X = 1, Y = 2 }] = 10;
        int v1 = 0, v2 = 0;
        for (int i = 0; i < 5; i++)
        {
            v1 += d1[new PlainKey { X = 1, Y = 2 }];
            v2 += d2[new FastKey { X = 1, Y = 2 }];
        }
        Console.WriteLine("lookups: " + v1 + " and " + v2);
        Console.WriteLine("PlainKey went through Equals(object) (boxing): " + (Stats.ObjectEquals > 0));
        Console.WriteLine("FastKey went through Equals(FastKey):          " + (Stats.TypedEquals > 0));
        Console.WriteLine("FastKey used boxed Equals(object): " + (Stats.ObjectEquals > 5));
    }
}
